   * PBKDF2 iteration instead of unsealing and resealing them.
   *
   * @deprecated The legacy seal fallback (and this option) will be removed in v3.
   */
  legacySealFallback?: boolean;
  crypto?: Crypto;
  /** Default is Crypto.randomUUID */
  generateId?: () => string;
}

